      // character for character whatever came before (an attribute that is removed and set again would move to the end).
      put(f.el, "data-fluid", alpha > 0 ? use[0] : "off");
      if (alpha <= 0) { put(f.el, "$opacity", ""); put(f.el, "$stroke-dashoffset", ""); continue; }
      put(f.el, "$opacity", alpha.toFixed(3));
