  const labels = [...root.querySelectorAll("[data-callout]")].map((el) => ({ el, id: el.dataset.callout, anchor: (el.dataset.anchor || "0,0").split(",").map(Number), line: el.querySelector(".callout-line"), words: el.querySelector(".callout-words") }));
