  const followers = [...root.querySelectorAll("[data-follow]")].map((el) => ({ el, order: Number(el.dataset.follow) }));
  const about = (el, scale) => { const [x, y] = el.dataset.focus.split(",").map(Number); return "translate(" + x + " " + y + ") scale(" + scale.toFixed(4) + ") translate(" + -x + " " + -y + ")"; }; // attribute syntax, see drawCamera
